story = {
    "id": "US-101",
    "narrative": "Como usuario nuevo, quiero crear una cuenta con email y contrasena, para acceder a mi panel",
    "acceptance_criteria": [
        {"id": "AC1", "desc": "el email tiene formato valido", "met": True},
        {"id": "AC2", "desc": "la contrasena tiene 8+ caracteres", "met": True},
        {"id": "AC3", "desc": "la cuenta queda creada", "met": True},
        {"id": "AC4", "desc": "el login funciona con las credenciales", "met": False},
    ],
}

def is_done(story):
    return all(ac["met"] for ac in story["acceptance_criteria"])

print(f"Historia {story['id']}: {story['narrative']}")
for ac in story["acceptance_criteria"]:
    estado = "OK" if ac["met"] else "PENDIENTE"
    print(f"  [{estado}] {ac['id']}: {ac['desc']}")

if is_done(story):
    print("Resultado: historia completa, lista para revision")
else:
    faltan = [ac["id"] for ac in story["acceptance_criteria"] if not ac["met"]]
    print(f"Resultado: historia incompleta, falta: {', '.join(faltan)}")
